import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.e4u2V5E7.js";const g=JSON.parse('{"title":"Seo","description":"Seo reference documentation","frontmatter":{"title":"Seo","description":"Seo reference documentation"},"headers":[],"relativePath":"knowledge/seo.md","filePath":"knowledge/seo.md","lastUpdated":1784485118000}'),n={name:"knowledge/seo.md"};function r(o,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="seo" tabindex="-1">Seo <a class="header-anchor" href="#seo" aria-label="Permalink to &quot;Seo&quot;">​</a></h1><h1 id="technical-seo-—-knowledge-base" tabindex="-1">Technical SEO — Knowledge Base <a class="header-anchor" href="#technical-seo-—-knowledge-base" aria-label="Permalink to &quot;Technical SEO — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Technical SEO ensures search engines can effectively crawl, index, and rank your website. This knowledge base covers meta tags, structured data, sitemaps, and SEO best practices for Next.js applications, with focus on App Router patterns and bilingual Arabic/English content.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="meta-tags-and-head-management" tabindex="-1">Meta Tags and Head Management <a class="header-anchor" href="#meta-tags-and-head-management" aria-label="Permalink to &quot;Meta Tags and Head Management&quot;">​</a></h3><p><strong>Title Tags</strong> — Unique, descriptive titles for every page. Include primary keyword near the beginning. Optimal length: 50-60 characters.</p><p><strong>Meta Descriptions</strong> — Summarize page content for search results. Not a ranking factor but affects click-through rate. Optimal length: 150-160 characters.</p><p><strong>Open Graph Tags</strong> — Control how content appears when shared on social media (Facebook, LinkedIn). Include <code>og:title</code>, <code>og:description</code>, <code>og:image</code>, <code>og:url</code>.</p><p><strong>Twitter Cards</strong> — Similar to OG but specific to Twitter/X. Use <code>twitter:card</code>, <code>twitter:title</code>, <code>twitter:description</code>, <code>twitter:image</code>.</p><h3 id="structured-data-schema-org" tabindex="-1">Structured Data (Schema.org) <a class="header-anchor" href="#structured-data-schema-org" aria-label="Permalink to &quot;Structured Data (Schema.org)&quot;">​</a></h3><p>JSON-LD markup that helps search engines understand content meaning and context.</p><p><strong>Common types:</strong></p><ul><li><code>WebSite</code> — Site-wide information</li><li><code>Organization</code> — Business details</li><li><code>Article</code> — Blog posts and news</li><li><code>Product</code> — E-commerce products</li><li><code>FAQPage</code> — Frequently asked questions</li><li><code>BreadcrumbList</code> — Navigation structure</li></ul><h3 id="sitemap-and-robots-txt" tabindex="-1">Sitemap and Robots.txt <a class="header-anchor" href="#sitemap-and-robots-txt" aria-label="Permalink to &quot;Sitemap and Robots.txt&quot;">​</a></h3><p><strong>Sitemap (sitemap.xml)</strong> — XML file listing all pages with last modification dates and priorities. Next.js generates sitemaps dynamically with <code>app/sitemap.ts</code>.</p><p><strong>Robots.txt</strong> — Instructions for crawlers on which pages to crawl and which to skip. Always reference the sitemap location.</p><h3 id="canonical-urls" tabindex="-1">Canonical URLs <a class="header-anchor" href="#canonical-urls" aria-label="Permalink to &quot;Canonical URLs&quot;">​</a></h3><p>Canonical tags tell search engines which version of a URL is the authoritative one, preventing duplicate content issues.</p><p><strong>Use cases:</strong></p><ul><li>Same content accessible via multiple URLs</li><li>HTTP and HTTPS versions</li><li>WWW and non-WWW versions</li><li>URL parameters for tracking</li></ul><h3 id="hreflang-tags" tabindex="-1">Hreflang Tags <a class="header-anchor" href="#hreflang-tags" aria-label="Permalink to &quot;Hreflang Tags&quot;">​</a></h3><p>Indicate language and regional targeting for multilingual sites. Critical for Arabic/English sites to prevent language confusion.</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alternate&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hreflang</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ar&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/ar/page&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alternate&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hreflang</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;en&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/en/page&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alternate&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hreflang</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;x-default&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/en/page&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="core-web-vitals-and-seo" tabindex="-1">Core Web Vitals and SEO <a class="header-anchor" href="#core-web-vitals-and-seo" aria-label="Permalink to &quot;Core Web Vitals and SEO&quot;">​</a></h3><p>Google uses Core Web Vitals as ranking signals:</p><ul><li>LCP affects perceived loading speed</li><li>CLS affects visual stability</li><li>INP affects interactivity</li></ul><h3 id="mobile-first-indexing" tabindex="-1">Mobile-First Indexing <a class="header-anchor" href="#mobile-first-indexing" aria-label="Permalink to &quot;Mobile-First Indexing&quot;">​</a></h3><p>Google primarily uses the mobile version of content for indexing and ranking. Ensure:</p><ul><li>Responsive design works on all screen sizes</li><li>Content is identical on mobile and desktop</li><li>Touch targets are appropriately sized</li><li>Viewport meta tag is set correctly</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Use Next.js generateMetadata</strong> — Export <code>generateMetadata</code> from page components for dynamic, per-page meta tags; supports Open Graph, Twitter, and standard meta</li><li><strong>Implement structured data with JSON-LD</strong> — Add schema.org markup to pages; use <code>next/script</code> for JSON-LD injection</li><li><strong>Generate dynamic sitemaps</strong> — Use <code>app/sitemap.ts</code> to create sitemaps from database content; include all public pages with proper lastmod dates</li><li><strong>Set canonical URLs consistently</strong> — Use <code>metadata.alternates.canonical</code> in Next.js to set canonical URLs; important for bilingual sites</li><li><strong>Implement hreflang for bilingual content</strong> — Use <code>metadata.alternates.languages</code> to link Arabic and English versions of each page</li><li><strong>Create descriptive breadcrumbs</strong> — Implement <code>BreadcrumbList</code> schema and visual breadcrumbs for navigation clarity</li><li><strong>Optimize for featured snippets</strong> — Structure content with clear headings, lists, and tables that search engines can extract for featured snippets</li><li><strong>Monitor with Google Search Console</strong> — Submit sitemaps, monitor indexing status, track search performance, and fix coverage issues</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Duplicate meta tags</strong> — Every page must have unique title and description; copying meta across pages confuses search engines</li><li><strong>Missing alt text on images</strong> — Search engines can&#39;t understand images without alt text; provide descriptive alt for all meaningful images</li><li><strong>Blocking CSS/JS in robots.txt</strong> — Search engines need CSS and JavaScript to render pages; never block these resources</li><li><strong>Using JavaScript redirects</strong> — Server-side redirects (301/302) are preferred; JavaScript redirects may not be followed by all crawlers</li><li><strong>Ignoring 404 errors</strong> — Broken links waste crawl budget and harm user experience; implement custom 404 pages and monitor for broken links</li><li><strong>Keyword stuffing</strong> — Repeating keywords unnaturally in content and meta tags is penalized; write naturally for humans</li><li><strong>Missing viewport meta tag</strong> — Without <code>&lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1&quot;&gt;</code>, mobile rendering fails</li><li><strong>Using client-side rendering for important content</strong> — Content rendered only in JavaScript may not be indexed; use Server Components</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Not setting metadataBase</strong> — Open Graph URLs require absolute URLs; set <code>metadataBase</code> in the root layout for proper OG image resolution</li><li><strong>Forgetting sitemap in robots.txt</strong> — Always reference your sitemap in robots.txt with <code>Sitemap: https://example.com/sitemap.xml</code></li><li><strong>Inconsistent URL structure</strong> — Changing URL patterns without redirects breaks existing backlinks and indexed pages</li><li><strong>Missing page load optimization for SEO pages</strong> — Blog posts and landing pages must load fast; Core Web Vitals affect rankings</li><li><strong>Not handling pagination SEO</strong> — Paginated content needs proper rel=&quot;next/prev&quot; or canonical to the first page</li><li><strong>Using the same image for OG across all pages</strong> — Each page should have a unique OG image representing its content</li><li><strong>Ignoring Arabic SEO specifics</strong> — Arabic content needs proper UTF-8 encoding, RTL markup, and Arabic-language keywords</li><li><strong>Not submitting sitemap to search engines</strong> — Don&#39;t wait for discovery; actively submit sitemaps to Google Search Console and Bing Webmaster Tools</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Recommendation</th></tr></thead><tbody><tr><td>New Next.js project</td><td>Set up metadataBase, generateMetadata, sitemap.ts from day one</td></tr><tr><td>Blog/CMS content</td><td>Article schema, proper heading hierarchy, Open Graph images</td></tr><tr><td>E-commerce</td><td>Product schema, price/availability markup, review aggregation</td></tr><tr><td>Bilingual site (AR/EN)</td><td>Hreflang tags, separate URL paths (/ar/, /en/), consistent content</td></tr><tr><td>Single Page Application</td><td>Server-side rendering for crawlable content; avoid CSR-only</td></tr><tr><td>Multi-tenant SaaS marketing</td><td>Each tenant&#39;s public pages need unique SEO metadata</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Google Search Central: <a href="https://developers.google.com/search" target="_blank" rel="noreferrer">https://developers.google.com/search</a></li><li>Next.js Metadata: <a href="https://nextjs.org/docs/app/building-your-application/optimizing/metadata" target="_blank" rel="noreferrer">https://nextjs.org/docs/app/building-your-application/optimizing/metadata</a></li><li>Schema.org: <a href="https://schema.org/" target="_blank" rel="noreferrer">https://schema.org/</a></li><li>Open Graph Protocol: <a href="https://ogp.me/" target="_blank" rel="noreferrer">https://ogp.me/</a></li><li>Ahrefs SEO Guide: <a href="https://ahrefs.com/seo" target="_blank" rel="noreferrer">https://ahrefs.com/seo</a></li><li>Moz Beginner&#39;s Guide to SEO: <a href="https://moz.com/beginners-guide-to-seo" target="_blank" rel="noreferrer">https://moz.com/beginners-guide-to-seo</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Next.js App Router:</strong> Use <code>generateMetadata()</code> and <code>export const metadata</code> for static metadata; generate dynamically for database-driven pages</li><li><strong>Sitemap generation:</strong> Use <code>app/sitemap.ts</code> with a function that queries Supabase for all public pages and returns URL entries</li><li><strong>Arabic content:</strong> Ensure proper UTF-8 encoding, use <code>lang=&quot;ar&quot;</code> on html element, and test with Arabic-specific search queries</li><li><strong>OG images:</strong> Generate dynamic OG images with <code>next/og</code> (Satori) for unique social sharing previews per page</li><li><strong>Monitoring:</strong> Set up Google Search Console for indexing monitoring; use Ahrefs or SEMrush for ongoing SEO analysis</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>`,44)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
